def _directory_records_sorted(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Project directory records and apply the documented response order.

    Collection responses reuse the same field projection as the single-record
    directory view (``get_directory_account`` / ``account_fields.public_account``)
    so that sensitive enrollment fields such as ``initial_password`` and
    ``recovery_token`` are never exposed across employees through the portal.
    """

    return sorted(
        (public_account(record) for record in records),
        key=lambda record: (record.get("username", ""), record.get("employee_id", "")),
    )


def list_accounts_by_department(department: str) -> list[dict[str, Any]]:
    """Return account directory records for one exact department."""

    return _directory_records_sorted(
        record for record in _load_accounts() if record.get("department") == department
    )


def list_accounts_by_host_group(host_group: str) -> list[dict[str, Any]]:
    """Return account directory records assigned to one exact host group."""

    return _directory_records_sorted(
        record for record in _load_accounts() if record.get("host_group") == host_group
    )


def count_accounts_by_department(department: str) -> int:
    """Return the number of accounts in one exact department."""

    return sum(
        1 for record in _load_accounts() if record.get("department") == department
    )
